const Auth = createContext(null), Toast = createContext(null)
const useAuth = () => useContext(Auth), useToast = () => useContext(Toast)

function Providers({ children }) {
  const [user, setUser] = useState(null), [toasts, setToasts] = useState([])
  useEffect(() => { api('/auth/me').then(setUser).catch(() => {}) }, [])
  const toast = (message, type = 'success') => { const id = Date.now(); setToasts((v) => [...v, { id, message, type }]); setTimeout(() => setToasts((v) => v.filter((x) => x.id !== id)), 3500) }
  return <Auth.Provider value={{ user, setUser }}><Toast.Provider value={toast}>{children}<div className="toast-stack">{toasts.map((x) => <div className={`toast ${x.type}`} key={x.id}>{x.type === 'success' ? <CheckCircle2 /> : <X />}{x.message}</div>)}</div></Toast.Provider></Auth.Provider>
}

function MotionObserver() {
  const location = useLocation()
  useEffect(() => {
    if (window.matchMedia('(prefers-reduced-motion: reduce)').matches) return undefined
    const selectors = [
      '.section-head', '.category-card', '.business-card', '.how-card', '.trust-list > div',
      '.trust-image', '.request-banner', '.profile-section', '.contact-card', '.stat-card',
      '.panel', '.matched-list article', '.offer-compare', '.admin-stat', '.verification-list article',
    ]
    const nodes = [...document.querySelectorAll(selectors.join(','))]
    nodes.forEach((node, index) => {
      node.classList.add('wonder-reveal')
      node.style.setProperty('--reveal-delay', `${Math.min(index % 6, 5) * 65}ms`)
    })
    const observer = new IntersectionObserver((entries) => entries.forEach((entry) => {
      if (entry.isIntersecting) { entry.target.classList.add('wonder-visible'); observer.unobserve(entry.target) }
    }), { threshold: 0.12, rootMargin: '0px 0px -35px' })
    nodes.forEach((node) => observer.observe(node))
    return () => observer.disconnect()
  }, [location.pathname, location.search])
  return null
}

